styles:
.rmcloak-stay-invisible{visibility:hidden}.rmcloak-stay-hidden{display:none}

/* SELECTION STATES */
*::selection {
    background: rgba(247, 121, 208, 1) !important;
    color: black !important;
}

[data-framer-name*="Form"] *::selection,
[data-framer-name*="Quote Pink"] *::selection {
  background: black !important;
  color: rgb(247, 121, 208) !important;
}

/* END SELECTION STATES */
/* FOCUS STATES */

*:focus-visible {
    outline: 3px dotted rgba(247,121,208) !important;
    outline-offset: 8px !important;
    border-radius: 8px !important;
    background: rgba(247, 121, 208, .25) !important;
}

[data-framer-name="navbar cards"] *:focus-visible {
border-radius: 0 !important;
outline: none !important;
background: initial !important;
}

[name="subscribe-button"] *:focus-visible,
[data-framer-name="Main Button"]:focus-visible {
    background: rgba(247, 121, 208, 1) !important;
}

[data-framer-name="Form Center Aligned"] button:focus-visible {
    background: rgba(0, 0, 0, 1) !important;
    outline: 3px dotted rgba(0,0,0) !important;
}

[name="Make More Money Button"] *:focus-visible {
    background: rgba(199, 255, 31, 1) !important;
    outline: 3px dotted rgba(199, 255, 31, 1) !important;    
}

[data-framer-name="jsFirstNameInput"],
[data-framer-name="jsEmailInput"] {
    overflow: visible !important;
}

input[type="text"]:focus-visible, 
input[type="email"]:focus-visible {
    border-radius: 0 !important;    
    outline: 3px dotted rgba(255, 255, 255, 1) !important;

    background: #fff !important;
    outline: 4px solid black !important;
    outline-offset: 0 !important;
} 

[aria-label="make-more-money-form"] input[type="text"]:focus-visible, 
[aria-label="make-more-money-form"] input[type="email"]:focus-visible {
    background: rgba(199, 255, 31, .2) !important;
    outline: 3px dotted rgba(199, 255, 31, 1) !important;
    background: #fff !important;
    outline: 4px solid rgba(199, 255, 31, 1) !important;
    outline-offset: 0 !important;

} 

[aria-label="make-more-money-form"] button[type="submit"]:focus {
    border-radius: 0 !important;
    background: #000 !important;
    outline: 4px solid rgba(199, 255, 31, 1) !important;
    outline-offset: 0 !important;
}

[aria-label="make-more-money-form"] button[type="submit"]:focus p {
    color: rgba(199, 255, 31, 1) !important;
}

/* END FOCUS STATES */
/* HOVER STATES */

[data-framer-name="navbar cards"] a {
    z-index: 1 !important;
}

[data-framer-name="navbar cards"] a:hover {
    z-index: 10 !important;
}

/* END HOVER STATES */
/* BUTTON CTA */
[aria-label="jsFlowerButton"] [data-framer-name="jsButtonFlowerLeaf"] {
    opacity: 0 !important;
    transition: all .35s ease;
}

[aria-label="jsFlowerButton"].hover [data-framer-name="jsButtonFlowerLeaf"] {
    opacity: 1 !important;
}

[aria-label="vertical-align"] svg {
    overflow: visible !important;
}

[aria-label="vertical-align"] p {
    padding-top: 20px !important;
}

[data-framer-name="main"] code.framer-text {
    color: #478AC2;
    font-size: 80%;
}

.framer-image.framer-text {
    width: 100%;
    margin-top: 2.4em !important;
    margin-bottom: 2.4em !important;
}

[data-framer-name="intro"] > ol.framer-text,
[data-framer-name="intro"] > ul.framer-text {
    overflow: hidden;
}

[aria-label="newsletterQuote"] [data-framer-name="quote-text"] p:first-child:before {
    content: "“";
    color: #F779D0;
}

[aria-label="newsletterQuote"] [data-framer-name="quote-text"] p:last-child:after {
    content: "”";
    color: #F779D0;
}

[aria-label="jsExcerptBlock"],
[aria-label="jsQuoteWhiteBlock"],
[aria-label="jsQuotePinkBlock"] {
    display: none !important;
}

.framer-form-text-input .framer-form-input {
    padding-left: 0.5em !important;
    text-indent: 0.5em;
}


